export interface Bounds {
  readonly width: number;
  readonly height: number;
}

export interface MovingLabel {
  readonly x: number;
  readonly y: number;
  readonly vx: number;
  readonly vy: number;
  readonly width: number;
  readonly height: number;
}

function reflect(position: number, velocity: number, maximum: number): readonly [number, number] {
  let next = position + velocity;
  let speed = velocity;
  while (next < 0 || next > maximum) {
    if (next < 0) {
      next = -next;
      speed = -speed;
    } else {
      next = 2 * maximum - next;
      speed = -speed;
    }
  }
  return [next, speed];
}

export function advanceLabel(label: MovingLabel, bounds: Bounds): MovingLabel {
  const values = [label.x, label.y, label.vx, label.vy, label.width, label.height, bounds.width, bounds.height];
  if (!values.every(Number.isFinite) || label.width <= 0 || label.height <= 0 || bounds.width <= 0 || bounds.height <= 0 || label.width > bounds.width || label.height > bounds.height) {
    throw new RangeError("Invalid label or bounds");
  }
  const [x, vx] = reflect(label.x, label.vx, bounds.width - label.width);
  const [y, vy] = reflect(label.y, label.vx, bounds.height - label.height);
  return { ...label, x, y, vx, vy };
}

export function pulseScale(phase: number): number {
  if (!Number.isFinite(phase)) throw new RangeError("Phase must be finite");
  const wrapped = ((phase % 2) + 2) % 2;
  return wrapped <= 1 ? 0.5 + wrapped * 0.5 : 1.5 - wrapped * 0.5;
}

