import { advanceLabel, Bounds, MovingLabel, pulseScale } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof RangeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const bounds: Bounds = { width: 12, height: 10 };
const label: MovingLabel = { x: 2, y: 3, width: 2, height: 2, vx: 3, vy: -2 };
const advanced = advanceLabel(label, bounds);
equal(advanced.x, 5, "ordinary x advance");
equal(advanced.y, 1, "ordinary y advance");
equal(advanced.vx, 3, "ordinary vx preserved");
equal(advanced.vy, -2, "ordinary vy preserved");
assert(advanced !== label, "advance returns fresh label");
equal(label.x, 2, "input x unchanged");
equal(label.y, 3, "input y unchanged");

const exact = advanceLabel({ x: 8, y: 2, width: 2, height: 2, vx: 2, vy: -2 }, bounds);
equal(exact.x, 10, "exact right contact position");
equal(exact.vx, 2, "exact right contact does not reverse");
equal(exact.y, 0, "exact top contact position");
equal(exact.vy, -2, "exact top contact does not reverse");

const crossed = advanceLabel({ x: 9, y: 1, width: 2, height: 2, vx: 4, vy: -4 }, bounds);
equal(crossed.x, 7, "right overshoot mirrored");
equal(crossed.vx, -4, "right crossing reverses velocity");
equal(crossed.y, 3, "top overshoot mirrored");
equal(crossed.vy, 4, "top crossing reverses velocity");

const repeated = advanceLabel({ x: 2, y: 1, width: 2, height: 2, vx: 25, vy: 19 }, bounds);
equal(repeated.x, 7, "multi-span horizontal overshoot reflected repeatedly");
equal(repeated.vx, 25, "multi-span horizontal final direction");
equal(repeated.y, 4, "multi-span vertical overshoot reflected repeatedly");
equal(repeated.vy, 19, "multi-span vertical final direction");

rangeError(() => advanceLabel(label, { width: 0, height: 10 }), "zero bounds");
rangeError(() => advanceLabel(label, { width: Infinity, height: 10 }), "non-finite bounds");
rangeError(() => advanceLabel({ ...label, width: -1 }, bounds), "negative label width");
rangeError(() => advanceLabel({ ...label, height: NaN }, bounds), "non-finite label height");
rangeError(() => advanceLabel({ ...label, x: Infinity }, bounds), "non-finite position");
rangeError(() => advanceLabel({ ...label, vy: NaN }, bounds), "non-finite velocity");

const phases: Array<[number, number]> = [
  [0, 0.5], [0.5, 0.75], [1, 1], [1.5, 0.75], [2, 0.5],
  [-0.5, 0.75], [-1, 1], [-1.5, 0.75], [-2, 0.5], [1001, 1]
];
for (const [phase, expected] of phases) equal(pulseScale(phase), expected, `pulse at ${phase}`);
rangeError(() => pulseScale(NaN), "NaN phase");
rangeError(() => pulseScale(Infinity), "infinite phase");

